using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Threading;using System.Threading.Tasks;
namespace QQImageSwitch
{
    static class QrAiLocationsTests
    {
        static void Require(bool okay,string message){if(!okay)throw new Exception("Model locations: "+message);}
        static object Call(string name,params object[] args){return typeof(QrAiService).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,args);}
        static void Tensor(string file){Directory.CreateDirectory(Path.GetDirectoryName(file));byte[] header=Encoding.UTF8.GetBytes("{\"weight\":{\"dtype\":\"F32\",\"shape\":[1],\"data_offsets\":[0,4]}}");using(var output=new BinaryWriter(File.Create(file))){output.Write((ulong)header.Length);output.Write(header);output.Write(new byte[4]);}}
        public static void Run(string root)
        {
            QrAiStorageTests.Run(root);
            string dir=Path.Combine(root,"model-location-tests"),settings=Path.Combine(dir,"settings.json");Directory.CreateDirectory(dir);
            string first=Path.Combine(dir,"first & 中文 models"),second=Path.Combine(dir,"changed models");Directory.CreateDirectory(first);Directory.CreateDirectory(second);
            var option=new QrAiOptions{Root=first,Base=Path.Combine(first,"custom.safetensors"),Control=""};QrAiService.SaveOptions(option,settings);var loaded=QrAiService.LoadOptions(settings);Require(loaded.Root==first&&loaded.Base==option.Base,"special-character selection was not restored");option.Root=second;QrAiService.SaveOptions(option,settings);Require(QrAiService.LoadOptions(settings).Root==second,"changed model root was not persisted");var saved=Inspection.Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(settings));Require(((System.Collections.IEnumerable)saved["Roots"]).Cast<object>().Contains(first),"previous cache root was forgotten");
            foreach(string malformed in new[]{"[]","null","{bad","{\"Roots\":[]}"}){File.WriteAllText(settings,malformed);Require(!string.IsNullOrEmpty(QrAiService.LoadOptions(settings).Root),"malformed settings crashed initialization");}
            string baseModel=Path.Combine(first,"base","custom-small");QrAiDirectoryProfileTests.CreateBase(baseModel,false);
            Require(QrAiService.Discover(first).Any(m=>m.Path==baseModel&&m.Family=="sd15"),"complete tiny pipeline was not found");
            var onlyBase=new QrAiOptions{Root=second,Base=baseModel};Require(((string[])Call("CustomWeightKinds",onlyBase)).SequenceEqual(new[]{"base"}),"existing base did not independently skip default weights");Require(((string[])Call("DownloadSearchRoots",onlyBase)).Contains(baseModel),"explicit selected model directory was omitted from reuse candidates");
            string sameName=Path.Combine(first,"custom","dreamshaper-8");Directory.CreateDirectory(sameName);foreach(string file in Directory.GetFiles(baseModel,"*",SearchOption.AllDirectories)){string to=Path.Combine(sameName,file.Substring(baseModel.Length+1));Directory.CreateDirectory(Path.GetDirectoryName(to));File.Copy(file,to);}
            var customSameName=new QrAiOptions{Root=second,Base=sameName};Require(Call("PinnedTarget",sameName,second)==null,"custom directory name was treated as official");Require(((string[])Call("CustomWeightKinds",customSameName)).SequenceEqual(new[]{"base"}),"same-name custom model would trigger duplicate default weight download");
            string unrelated=Path.Combine(sameName,"unrelated","deep","broken.safetensors");Directory.CreateDirectory(Path.GetDirectoryName(unrelated));File.WriteAllText(unrelated,"not a model");((Task)Call("VerifySelectedModels",customSameName,(Action<string>)(s=>{}),CancellationToken.None)).GetAwaiter().GetResult();Require(!File.ReadAllText(Path.Combine(second,"custom-model-hashes.json")).Contains("unrelated"),"custom directory validation traversed unrelated files");
            bool rejectedRoot=false;try{((Task)Call("VerifySelectedModels",new QrAiOptions{Root=second,Base=first},(Action<string>)(s=>{}),CancellationToken.None)).GetAwaiter().GetResult();}catch(InvalidDataException){rejectedRoot=true;}Require(rejectedRoot,"an arbitrary non-model directory was accepted for recursive hashing");
            string control=QrAiIntegrityTests.Model("location-control",768,false,false,true);var onlyControl=new QrAiOptions{Root=second,Control=control};Require(((string[])Call("CustomWeightKinds",onlyControl)).SequenceEqual(new[]{"controlnet"}),"existing ControlNet did not independently skip default weights");
            var lines=new List<string>();((Task)Call("VerifySelectedModels",onlyControl,(Action<string>)(s=>lines.Add(s)),CancellationToken.None)).GetAwaiter().GetResult();string hashes=Path.Combine(second,"custom-model-hashes.json");Require(File.ReadAllText(hashes).Contains(QrAiIntegrity.Inspect(control,true).Sha256)&&lines.Count>0,"custom model hash/progress was not recorded");byte[] data=File.ReadAllBytes(control);data[data.Length-1]^=1;File.WriteAllBytes(control,data);lines.Clear();((Task)Call("VerifySelectedModels",onlyControl,(Action<string>)(s=>lines.Add(s)),CancellationToken.None)).GetAwaiter().GetResult();Require(lines.Any(s=>s.Contains(L.T("自定义模型内容已变化，本次已重新校验。"))),"custom model content change was not detected");
            string componentFile=Path.Combine(baseModel,"unet","model.safetensors");data=File.ReadAllBytes(componentFile);File.WriteAllBytes(componentFile,data.Take(data.Length-1).ToArray());Require(!QrAiService.Discover(first).Any(m=>m.Path==baseModel),"truncated pipeline appeared as ready");
            File.WriteAllText(Path.Combine(dir,"PASS.md"),"PASS: special-character model paths, saved root changes/history, malformed settings, standalone partial model selection skip, selected external search roots, same-name custom model not official or duplicated, only defined component files hashed, arbitrary roots rejected, custom whole-file SHA/progress/change detection, and truncated Diffusers component rejection. All fixtures are small owned files; no real model copied.");
        }
    }
}
